sys_script_email.script:
// Notification Email Script name: clm_nt_ask_for_approval_script
// Notification table: sysapproval_approver
// Handles Non-Trade PAN Credit Limit (Email + Portal Actions) & Limit Swap (Email + Portal Actions)
(function runMailScript(current, template, email, email_action, event) {
    try {
        // ── 1. Helpers & Parsers (Aligned with Trade CredX UI) ─────────────
        function s(v) {
            return (v === null || v === undefined) ? '' : String(v).trim();
        }

        function parseNum(v) {
            if (!v && v !== 0) return 0;
            var strVal = String(v);
            if (strVal.indexOf(';') > -1) strVal = strVal.split(';')[1];
            var num = parseFloat(strVal);
            return isNaN(num) ? 0 : num;
        }

        function inr(n) {
            var str = Math.round(Math.abs(parseNum(n))).toString();
            var last = str.slice(-3),
                rest = str.slice(0, -3);
            if (rest) last = rest.replace(/\B(?=(\d{2})+(?!\d))/g, ',') + ',' + last;
            return last;
        }

        function rupee(n) {
            var num = parseNum(n);
            return (num < 0 ? '- &#8377; ' : '&#8377; ') + inr(num);
        }

        function esc(str) {
            return GlideStringUtil.escapeHTML(s(str));
        }

        // ── PAN-Level Calculation & Approver Recommended CL Helpers ──────────
        function segKey(t) {
            t = (t || '').toString().toLowerCase();
            if (t.indexOf('cement') !== -1) return 'Cement';
            if (t.indexOf('rmc') !== -1) return 'RMC';
            if (t.indexOf('bpd') !== -1) return 'BPD';
            return '';
        }

        function getSiteCode(sGr) {
            var code = s(sGr.getValue('customer_code'));
            if (!code && sGr.isValidField('customer_site_code') && sGr.customer_site_code) {
                code = sGr.customer_site_code.customer_code_sap ? s(sGr.customer_site_code.customer_code_sap) : '';
            }
            return code;
        }

        function getPanListFigures(panSysId, panVal) {
            var reqMap = {};
            var sGr = new GlideRecord('x_birl3_clm_nt_site_request');
            sGr.addQuery('pan_request', panSysId);
            sGr.query();
            while (sGr.next()) {
                var code = getSiteCode(sGr);
                var seg = sGr.isValidField('segment') ? segKey(sGr.getDisplayValue('segment')) : '';
                reqMap[code + '|' + seg] = {
                    requested: parseNum(sGr.getValue('requested_limit') || sGr.getValue('site_desired_limit')),
                    os: parseNum(sGr.getValue('existing_outstanding'))
                };
            }

            var snapOs = {};
            var snGr = new GlideRecord('x_birl3_clm_nt_pan_request_outstanding');
            snGr.addQuery('pan_request', panSysId);
            snGr.orderByDesc('snapshot_month');
            snGr.orderByDesc('sys_created_on');
            snGr.query();
            while (snGr.next()) {
                var sk = s(snGr.getValue('customer_site_code') || snGr.getValue('customer'));
                var ck = s(snGr.getValue('customer_code'));
                if ((sk && snapOs[sk] === undefined) || (ck && snapOs[ck] === undefined)) {
                    var isLeg = snGr.isValidField('bucket_0_21_days') && snGr.getValue('bucket_0_21_days') !== null;
                    var b03 = parseNum(isLeg ? snGr.getValue('bucket_0_21_days') : snGr.getValue('bucket_0_30_days'));
                    var b47 = parseNum(isLeg ? snGr.getValue('bucket_22_30_days') : snGr.getValue('bucket_31_45_days'));
                    var b821 = parseNum(isLeg ? snGr.getValue('bucket_31_45_days') : snGr.getValue('bucket_46_60_days'));
                    var b22 = parseNum(isLeg ? snGr.getValue('bucket_46_60_days') : snGr.getValue('bucket_61_75_days'));
                    var b31 = parseNum(isLeg ? snGr.getValue('bucket_61_75_days') : snGr.getValue('bucket_76_90_days'));
                    var bgt = parseNum(snGr.getValue('bucket_gt120_days')) + parseNum(snGr.getValue('bucket_91_120_days'));
                    var tot = parseNum(snGr.getValue('total_outstanding')) || (b03 + b47 + b821 + b22 + b31 + bgt);
                    if (sk && snapOs[sk] === undefined) snapOs[sk] = tot;
                    if (ck && snapOs[ck] === undefined) snapOs[ck] = tot;
                }
            }

            var requestedPan = 0,
                outstanding = 0;
            var seen = {},
                claimed = {};
            var cGr = new GlideRecord('x_birl3_clm_clm_customer_master1');
            cGr.addQuery('pan', panVal);
            cGr.addQuery('cg1', 'N01');
            cGr.query();
            while (cGr.next()) {
                var cId = cGr.getUniqueValue();
                var cCode = s(cGr.getValue('customer_code_sap'));
                var cSeg = segKey(cGr.getDisplayValue('segment'));
                var dedupe = cCode ? (cCode + '|' + cSeg) : cId;
                if (seen[dedupe]) continue;
                seen[dedupe] = true;

                var key = cCode + '|' + cSeg;
                if (reqMap[key] === undefined && reqMap[cCode + '|'] !== undefined) key = cCode + '|';
                var line = (reqMap[key] !== undefined && !claimed[key]) ? reqMap[key] : null;
                if (line) claimed[key] = true;

                var curCl = parseNum(cGr.getValue('cr_limit') || cGr.getValue('credit_limit'));
                requestedPan += line ? line.requested : curCl;

                if (snapOs[cId] !== undefined) outstanding += snapOs[cId];
                else if (cCode && snapOs[cCode] !== undefined) outstanding += snapOs[cCode];
                else outstanding += line ? line.os : parseNum(cGr.getValue('outstanding'));
            }

            return {
                requestedPan: requestedPan,
                outstanding: outstanding
            };
        }

        function getRecommendedCl(appGr) {
            if (!appGr || !appGr.isValidField('approval_journal_column')) return 0;
            var raw = '';
            try {
                var el = appGr.getElement('approval_journal_column');
                if (el) raw = el.getJournalEntry(1) || '';
            } catch (e) {
                raw = '';
            }
            if (!raw) raw = appGr.getValue('approval_journal_column') || '';
            if (!raw) return 0;

            var lines = String(raw).split('\n');
            if (lines.length > 1 && /^\d{4}-\d{2}-\d{2}|^[^:]+:\s*\d{4}-\d{2}-\d{2}/.test(lines[0])) lines.shift();
            var txt = lines.join(' ').replace(/[,₹\s]/g, '');
            var m = txt.match(/\d+(\.\d+)?/);
            return m ? (parseFloat(m[0]) || 0) : 0;
        }

        // ── Shared CredX UI Component Builders ─────────────────────────────
        var TD_K = 'padding:8px 0; color:#5a6a7a; border-bottom:1px solid #eef1f5;';
        var TD_V = 'padding:8px 0; color:#1a1a1a; border-bottom:1px solid #eef1f5;';
        var TILE = 'border:1px solid #e0e6ed; border-radius:6px; padding:12px 14px; background-color:#fafbfc;';
        var TILE_K = 'font-size:10px; text-transform:uppercase; letter-spacing:.8px; color:#5a6a7a; font-weight:700;';

        function sec(title, top) {
            return '<h3 style="margin:' + (top || 24) + 'px 0 8px 0; font-size:13px; text-transform:uppercase; letter-spacing:1px; color:#1a1a1a; border-bottom:2px solid #F3D54E; padding-bottom:6px;">' + title + '</h3>';
        }

        function kv(label, value, last, bold) {
            return '<tr><td width="38%" style="' + (last ? 'padding:8px 0; color:#5a6a7a;' : TD_K) + '">' + label + '</td>' +
                '<td style="' + (last ? 'padding:8px 0; color:#1a1a1a;' : TD_V) + (bold ? ' font-weight:700;' : '') + '">' + value + '</td></tr>';
        }

        function renderApprovalHistory(parentGr, amountVal, amountHeader) {
            var pId = parentGr.getUniqueValue();
            var ap = new GlideRecord('sysapproval_approver');
            var apq = ap.addQuery('document_id', pId);
            apq.addOrCondition('sysapproval', pId);
            ap.addQuery('state', 'IN', 'approved,rejected');
            if (parentGr.isValidField('u_last_submitted_on') && s(parentGr.getValue('u_last_submitted_on'))) {
                ap.addQuery('sys_created_on', '>=', s(parentGr.getValue('u_last_submitted_on')));
            }
            ap.orderBy('sys_updated_on');
            ap.query();

            var H_TH = 'padding:9px 12px; background-color:#eef1f5; color:#2b3440; font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.5px; text-align:left; border-bottom:1px solid #dde3ea;';
            var H_TD = 'padding:10px 12px; font-size:13px; color:#1a1a1a; border-bottom:1px solid #eef1f5; vertical-align:top;';
            var histRows = '',
                histCount = 0;

            while (ap.next()) {
                histCount++;
                var apState = s(ap.getValue('state'));
                var roleBadge = s(ap.getValue('approval_reason')) || (apState === 'approved' ? 'Approved' : 'Rejected');
                var comment = '';

                var jf = new GlideRecord('sys_journal_field');
                jf.addQuery('element_id', ap.getUniqueValue());
                jf.addQuery('element', 'comments');
                jf.orderByDesc('sys_created_on');
                jf.setLimit(1);
                jf.query();
                if (jf.next()) {
                    comment = s(jf.getValue('value'));
                }

                if (!comment && ap.comments) {
                    var jEntry = s(ap.comments.getJournalEntry(1));
                    if (jEntry) {
                        var lines = jEntry.split('\n');
                        if (lines.length > 1) {
                            lines.shift();
                            comment = lines.join('\n').trim();
                        } else {
                            comment = jEntry.trim();
                        }
                    }
                }

                if (!comment) {
                    comment = s(ap.getValue('comments'));
                }

                var recCl = getRecommendedCl(ap);
                var dispAmt = recCl > 0 ? recCl : amountVal;
                var stateIcon = apState === 'approved' ?
                    '<span style="color:#27ae60; font-weight:700;">&#10004;</span>' :
                    '<span style="color:#E23D28; font-weight:700;">&#10006;</span>';

                histRows += '<tr>';
                histRows += '<td style="' + H_TD + '"><div style="font-weight:700;">' + stateIcon + ' ' + esc(ap.approver.getDisplayValue()) + '</div>' +
                    '<div style="padding-top:4px;"><span style="display:inline-block; background-color:#eef1f5; border:1px solid #dde3ea; border-radius:4px; padding:2px 8px; font-size:11px; font-weight:700; color:#2b3440;">' + esc(roleBadge) + '</span></div></td>';
                histRows += '<td style="' + H_TD + ' white-space:nowrap; font-weight:700;">' + (apState === 'approved' ? rupee(dispAmt) : '&mdash;') + '</td>';
                histRows += '<td style="' + H_TD + ' white-space:pre-wrap; word-break:break-word;">' + (comment ? esc(comment) : '<span style="color:#8a96a3;">&mdash;</span>') +
                    '<div style="font-size:11px; color:#8a96a3; padding-top:4px;">' + esc(ap.getDisplayValue('sys_updated_on')) + '</div></td>';
                histRows += '</tr>';
            }

            var out = sec('Approval History' + (histCount ? ' <span style="display:inline-block; background-color:#eef1f5; border:1px solid #dde3ea; border-radius:10px; padding:0 8px; font-size:11px; letter-spacing:0; color:#2b3440;">' + histCount + '</span>' : ''));
            if (histCount) {
                out += '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="border:1px solid #dde3ea; border-radius:6px;"><thead><tr>' +
                    '<th style="' + H_TH + '">Approver</th><th style="' + H_TH + '">' + esc(amountHeader || 'Recommended Limit') + '</th><th style="' + H_TH + '">Comments</th></tr></thead><tbody>' + histRows + '</tbody></table>';
            } else {
                out += '<p style="margin:0; font-size:13px; color:#5a6a7a;">No earlier approvals &mdash; you are the first approver on this request.</p>';
            }
            return out;
        }

        // ── 2. Resolve Target Parent Table & Record ────────────────────────
        var targetTable = s(current.getValue('source_table'));
        var targetSysId = s(current.getValue('document_id'));

        if (!targetTable && current.sysapproval) {
            targetSysId = current.getValue('sysapproval');
            var taskCheck = new GlideRecord('task');
            if (taskCheck.get(targetSysId)) {
                targetTable = taskCheck.getRecordClassName();
            } else {
                targetTable = current.sysapproval.sys_class_name.toString();
            }
        } else if (targetTable && !targetSysId && current.sysapproval) {
            targetSysId = current.getValue('sysapproval');
        }

        var instanceUrl = gs.getProperty('glide.servlet.uri');
        if (!instanceUrl.endsWith('/')) instanceUrl += '/';

        var instanceEmail = 'snsupportdev@adityabirla.com';
        var approvalNumber = s(current.getValue('number')); // SYSAPPxxxxxxx
        var approverName = current.approver ? s(current.approver.getDisplayValue()) : 'Approver';
        var h = '';

        // ── 3. Resolve ServiceNow Watermark for Inbound Actions ────────────
        var watermarkMsg = '';
        if (typeof email !== 'undefined' && email.watermark) {
            watermarkMsg = email.watermark;
        }
        if (!watermarkMsg) {
            var wmGr = new GlideRecord('sys_watermark');
            wmGr.addQuery('source_id', current.getUniqueValue());
            wmGr.orderByDesc('sys_created_on');
            wmGr.setLimit(1);
            wmGr.query();
            if (wmGr.next()) {
                watermarkMsg = wmGr.getValue('number') || '';
            }
        }
        if (watermarkMsg && watermarkMsg.indexOf('Ref:') === -1) {
            watermarkMsg = 'Ref:' + watermarkMsg;
        }

        // Pre-populate "Comments:" on line 1 while preserving the ServiceNow watermark below
        var commentMailtoBody = encodeURIComponent('Comments: \n\n' + watermarkMsg);

        // ── 4. Branch A: Non-Trade Credit Limit Request (Email + Portal Actions) ─
        if (targetTable === 'x_birl3_clm_nt_pan_request') {
            var panGr = new GlideRecord('x_birl3_clm_nt_pan_request');
            if (!panGr.get(targetSysId)) {
                template.print('<div style="font-family: Arial, sans-serif; color: #d9534f;">Unable to retrieve Non-Trade CL request details.</div>');
                return;
            }

            var panSysId = panGr.getUniqueValue();
            var reqNumber = s(panGr.getValue('number'));
            var panStr = s(panGr.getValue('pan'));
            var segment = panGr.getDisplayValue('segment') || s(panGr.getValue('segment')) || 'Non-Trade';
            var panFigs = panStr ? getPanListFigures(panSysId, panStr) : {
                requestedPan: 0,
                outstanding: 0
            };
            var requestedLimit = panFigs.requestedPan || parseNum(panGr.getValue('total_requested_limit') || panGr.getValue('total_desired_limit'));
            var safeLimit = parseNum(panGr.getValue('total_safe_allowable_limit'));
            var outstanding = panFigs.outstanding || parseNum(panGr.getValue('total_outstanding_pan'));
            var isDeviation = (panGr.getValue('is_deviation') == 1 || panGr.getValue('is_deviation') == 'true');
            var initiator = panGr.opened_by ? s(panGr.opened_by.getDisplayValue()) : 'Initiator';

            var custName = 'Corporate Group';
            if (panStr) {
                var custGr = new GlideRecord('x_birl3_clm_clm_customer_master1');
                custGr.addQuery('pan', panStr);
                custGr.setLimit(1);
                custGr.query();
                if (custGr.next()) {
                    custName = custGr.getValue('group_customer_name') || custGr.getValue('customer_name') || custGr.getValue('name') || custName;
                }
            }

            email.setSubject('[CredX] Action Required: Non-Trade Credit Limit Approval - ' + reqNumber + ' (' + (custName !== 'Corporate Group' ? custName : panStr) + ')');

            var portalUrl = instanceUrl + 'uclm?id=uclm_non_trade_approval&number=' + encodeURIComponent(reqNumber);

            var clRefNumber = approvalNumber || reqNumber;
            var clApproveSubject = encodeURIComponent('Re: ' + clRefNumber + ' - Approve');
            var clRejectSubject = encodeURIComponent('Re: ' + clRefNumber + ' - Reject');
            var clMailtoApprove = 'mailto:' + instanceEmail + '?subject=' + clApproveSubject + '&body=' + commentMailtoBody;
            var clMailtoReject = 'mailto:' + instanceEmail + '?subject=' + clRejectSubject + '&body=' + commentMailtoBody;

            var actionPill = '<span style="display:inline-block; background-color:#fff3cd; color:#856404; border:1px solid #ffe69c; border-radius:4px; padding:3px 10px; font-size:11px; font-weight:700; letter-spacing:.5px; text-transform:uppercase;">Action Required</span>';
            var devPill = isDeviation ?
                ' <span style="display:inline-block; background-color:#E23D28; color:#ffffff; border:1px solid #b82b1c; border-radius:4px; padding:3px 10px; font-size:11px; font-weight:700; letter-spacing:.5px; text-transform:uppercase;">Deviation</span>' :
                ' <span style="display:inline-block; background-color:#eafaf1; color:#1e8449; border:1px solid #a9dfbf; border-radius:4px; padding:3px 10px; font-size:11px; font-weight:700; letter-spacing:.5px; text-transform:uppercase;">Standard</span>';

            h += '<p style="margin:0 0 4px 0; font-size:14px; color:#5a6a7a;">Dear ' + esc(approverName) + ',</p>';
            h += '<h1 style="margin:10px 0 6px 0; font-size:22px; line-height:1.3; color:#1a1a1a; font-weight:700;">A credit limit request is awaiting your approval</h1>';
            h += '<p style="margin:0 0 20px 0; font-size:14px; color:#5a6a7a;">A Non-Trade credit limit revision has been submitted by <b style="color:#1a1a1a;">' + esc(initiator) + '</b>. Please review the details below and take a decision via email or in CredX.</p>';

            h += '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background-color:#fffcf0; border:1px solid #F3D54E; border-radius:6px;"><tbody><tr>';
            h += '<td style="padding:12px 16px;">';
            h += '<div style="font-size:11px; text-transform:uppercase; letter-spacing:1px; color:#5a6a7a; font-weight:700;">Request Number</div>';
            h += '<div style="font-size:18px; font-weight:700; color:#1a1a1a;">' + esc(reqNumber) + '</div>';
            h += '<div style="font-size:12px; padding-top:3px;"><a href="' + portalUrl + '" style="color:#AF272F; font-weight:700; text-decoration:none;">Review in CredX &rarr;</a></div>';
            h += '</td>';
            h += '<td align="right" valign="middle" style="padding:12px 16px;">' + actionPill + devPill + '</td>';
            h += '</tr></tbody></table>';

            if (isDeviation) {
                h += '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="margin-top:16px; background-color:#FDEDEC; border-left:4px solid #E23D28; border-radius:4px;"><tbody><tr><td style="padding:12px 16px;">';
                h += '<div style="font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.5px; color:#b3261e; margin-bottom:4px;">&#9888; Deviation Warning</div>';
                h += '<div style="font-size:13px; line-height:1.5; color:#1a1a1a;">The requested credit limit exceeds the calculated Safe Allowable Limit and requires authorized matrix exception approval.</div>';
                h += '</td></tr></tbody></table>';
            }

            h += sec('Customer', 28);
            h += '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="font-size:14px;"><tbody>';
            h += kv('Customer Group', esc(custName), false, true);
            h += kv('Corporate PAN', '<span style="font-family:monospace; font-weight:700;">' + esc(panStr || '&mdash;') + '</span>');
            h += kv('Customer Type', 'Non-Trade');
            h += kv('Segment', esc(segment));
            h += kv('Submitted By', esc(initiator));
            h += kv('Approval Status', '<span style="color:#856404; font-weight:700;">Awaiting Your Decision</span>', true, true);
            h += '</tbody></table>';

            h += sec('Credit Limit (PAN Level)');
            h += '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0"><tbody><tr>';
            h += '<td width="33%" valign="top" style="padding-right:6px;"><div style="' + TILE + '"><div style="' + TILE_K + '">Total PAN Outstanding</div><div style="font-size:17px; font-weight:700; padding-top:3px;">' + rupee(outstanding) + '</div></div></td>';
            h += '<td width="34%" valign="top" style="padding:0 3px;"><div style="' + TILE + '"><div style="' + TILE_K + '">Safe Allowable Limit</div><div style="font-size:17px; font-weight:700; color:#1e8449; padding-top:3px;">' + rupee(safeLimit) + '</div></div></td>';
            h += '<td width="33%" valign="top" style="padding-left:6px;"><div style="background-color:#fffcf0; border:1px solid #F3D54E; border-radius:6px; padding:12px 14px;"><div style="' + TILE_K + '">Requested PAN Limit</div><div style="font-size:17px; font-weight:700; padding-top:3px;">' + rupee(requestedLimit) + '</div></div></td>';
            h += '</tr></tbody></table>';

            var siteGr = new GlideRecord('x_birl3_clm_nt_site_request');
            siteGr.addQuery('pan_request', panGr.getUniqueValue());
            siteGr.orderBy('customer_site_code');
            siteGr.query();

            var TH = 'padding:9px 12px; background-color:#eef1f5; color:#2b3440; font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.5px; text-align:left; border-bottom:1px solid #dde3ea;';
            var TH_R = 'padding:9px 12px; background-color:#eef1f5; color:#2b3440; font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.5px; text-align:right; border-bottom:1px solid #dde3ea;';
            var TD = 'padding:10px 12px; font-size:13px; color:#1a1a1a; border-bottom:1px solid #eef1f5; vertical-align:top;';
            var TD_R = 'padding:10px 12px; font-size:13px; color:#1a1a1a; border-bottom:1px solid #eef1f5; vertical-align:top; text-align:right; white-space:nowrap;';

            var siteRows = '',
                siteCount = 0;
            while (siteGr.next()) {
                siteCount++;
                var sCode = getSiteCode(siteGr) || siteGr.getDisplayValue('customer_site_code') || siteGr.getValue('customer_code_sap') || 'N/A';
                var sName = (siteGr.customer_site_code && siteGr.customer_site_code.customer_name) ?
                    (siteGr.customer_site_code.customer_name.getValue() || 'Site') :
                    'Site';
                var sCurrLimit = parseNum(siteGr.getValue('existing_credit_limit'));
                var sReqLimit = parseNum(siteGr.getValue('requested_limit') || siteGr.getValue('site_desired_limit'));

                siteRows += '<tr>';
                siteRows += '<td style="' + TD + ' font-family:monospace; font-weight:700; white-space:nowrap;">' + esc(sCode) + '</td>';
                siteRows += '<td style="' + TD + '">' + esc(sName) + '</td>';
                siteRows += '<td style="' + TD_R + ' color:#5a6a7a;">' + rupee(sCurrLimit) + '</td>';
                siteRows += '<td style="' + TD_R + ' font-weight:700;">' + rupee(sReqLimit) + '</td>';
                siteRows += '</tr>';
            }

            if (siteCount) {
                h += sec('Site Level Allocation <span style="display:inline-block; background-color:#eef1f5; border:1px solid #dde3ea; border-radius:10px; padding:0 8px; font-size:11px; letter-spacing:0; color:#2b3440;">' + siteCount + '</span>');
                h += '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="border:1px solid #dde3ea; border-radius:6px;"><thead><tr>';
                h += '<th style="' + TH + '">Site Code</th>';
                h += '<th style="' + TH + '">Site Name</th>';
                h += '<th style="' + TH_R + '">Current Limit</th>';
                h += '<th style="' + TH_R + '">Requested Limit</th>';
                h += '</tr></thead><tbody>' + siteRows + '</tbody></table>';
            }

            h += renderApprovalHistory(panGr, requestedLimit, 'Recommended Limit');

            // Direct Email & Portal Actions Block
            h += sec('Take Decision');
            h += '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background-color:#fafbfc; border:1px solid #e0e6ed; border-radius:6px;"><tbody><tr><td style="padding:16px 18px;">';
            h += '<div style="font-size:12px; color:#5a6a7a; margin-bottom:12px;">Approve the full requested PAN limit or reject directly via email, or open the request in CredX to adjust the limit or raise an RFI:</div>';
            h += '<table role="presentation" border="0" cellspacing="0" cellpadding="0"><tbody><tr>';
            h += '<td style="padding-right:10px;">';
            h += '<a href="' + clMailtoApprove + '" target="_blank" style="display:inline-block; background-color:#27ae60; color:#ffffff; text-decoration:none; font-size:12px; font-weight:700; letter-spacing:.5px; text-transform:uppercase; padding:11px 20px; border-radius:6px;">&#10004; Approve via Email</a>';
            h += '</td>';
            h += '<td style="padding-right:10px;">';
            h += '<a href="' + clMailtoReject + '" target="_blank" style="display:inline-block; background-color:#E23D28; color:#ffffff; text-decoration:none; font-size:12px; font-weight:700; letter-spacing:.5px; text-transform:uppercase; padding:11px 20px; border-radius:6px;">&#10006; Reject via Email</a>';
            h += '</td>';
            h += '<td>';
            h += '<a href="' + portalUrl + '" target="_blank" style="display:inline-block; background-color:#1a1a1a; border-bottom:3px solid #F3D54E; color:#ffffff; text-decoration:none; font-size:12px; font-weight:700; letter-spacing:.5px; text-transform:uppercase; padding:11px 20px; border-radius:6px;">Review in Portal</a>';
            h += '</td>';
            h += '</tr></tbody></table>';
            h += '</td></tr></tbody></table>';

            template.print(h);
            return;
        }

        // ── 5. Branch B: Non-Trade Limit Swap Request (Email + Portal Actions) ──
        if (targetTable === 'x_birl3_clm_nt_limit_swap_request') {
            var swapGr = new GlideRecord('x_birl3_clm_nt_limit_swap_request');
            if (!swapGr.get(targetSysId)) {
                template.print('<div style="font-family: Arial, sans-serif; color: #d9534f;">Unable to retrieve Limit Swap request details.</div>');
                return;
            }

            var swapNumber = s(swapGr.getValue('number'));
            var swapAmount = parseNum(swapGr.getValue('requested_amount'));
            var swapInitiator = swapGr.opened_by ? s(swapGr.opened_by.getDisplayValue()) : (s(swapGr.getValue('sys_created_by')) || 'Initiator');

            var donorGr = swapGr.donor.getRefRecord();
            var doneeGr = swapGr.donee.getRefRecord();

            var donorCode = (donorGr && donorGr.isValidRecord()) ?
                (donorGr.getValue('customer_code_sap') || donorGr.getValue('customer_code') || '') :
                s(swapGr.getValue('donor_site_code'));
            var donorName = (donorGr && donorGr.isValidRecord()) ?
                (donorGr.getValue('customer_name') || donorGr.getValue('group_customer_name') || '') :
                s(swapGr.getDisplayValue('donor'));

            var doneeCode = (doneeGr && doneeGr.isValidRecord()) ?
                (doneeGr.getValue('customer_code_sap') || doneeGr.getValue('customer_code') || '') :
                s(swapGr.getValue('donee_site_code'));
            var doneeName = (doneeGr && doneeGr.isValidRecord()) ?
                (doneeGr.getValue('customer_name') || doneeGr.getValue('group_customer_name') || '') :
                s(swapGr.getDisplayValue('donee'));

            var donorCurrentLimit = parseNum(swapGr.getValue('donor_current_limit'));
            var doneeCurrentLimit = parseNum(swapGr.getValue('donee_current_limit'));
            var donorPostLimit = donorCurrentLimit - swapAmount;
            var doneePostLimit = doneeCurrentLimit + swapAmount;

            email.setSubject('[CredX] Action Required: Limit Swap Approval - ' + swapNumber + ' (' + donorCode + ' → ' + doneeCode + ')');

            var swapPortalUrl = instanceUrl + 'uclm?id=uclm_limit_swap_approval&number=' + encodeURIComponent(swapNumber);

            var swapRefNumber = approvalNumber || swapNumber;
            var swapApproveSubject = encodeURIComponent('Re: ' + swapRefNumber + ' - Approve');
            var swapRejectSubject = encodeURIComponent('Re: ' + swapRefNumber + ' - Reject');
            var mailtoApprove = 'mailto:' + instanceEmail + '?subject=' + swapApproveSubject + '&body=' + commentMailtoBody;
            var mailtoReject = 'mailto:' + instanceEmail + '?subject=' + swapRejectSubject + '&body=' + commentMailtoBody;

            var swapActionPill = '<span style="display:inline-block; background-color:#fff3cd; color:#856404; border:1px solid #ffe69c; border-radius:4px; padding:3px 10px; font-size:11px; font-weight:700; letter-spacing:.5px; text-transform:uppercase;">Action Required</span>';
            var swapTypePill = ' <span style="display:inline-block; background-color:#d6eaf8; color:#2980b9; border:1px solid #aed6f1; border-radius:4px; padding:3px 10px; font-size:11px; font-weight:700; letter-spacing:.5px; text-transform:uppercase;">Limit Swap</span>';

            h += '<p style="margin:0 0 4px 0; font-size:14px; color:#5a6a7a;">Dear ' + esc(approverName) + ',</p>';
            h += '<h1 style="margin:10px 0 6px 0; font-size:22px; line-height:1.3; color:#1a1a1a; font-weight:700;">A limit swap request is awaiting your approval</h1>';
            h += '<p style="margin:0 0 20px 0; font-size:14px; color:#5a6a7a;">A credit limit reallocation request has been submitted by <b style="color:#1a1a1a;">' + esc(swapInitiator) + '</b> and is awaiting your review.</p>';

            h += '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background-color:#fffcf0; border:1px solid #F3D54E; border-radius:6px;"><tbody><tr>';
            h += '<td style="padding:12px 16px;">';
            h += '<div style="font-size:11px; text-transform:uppercase; letter-spacing:1px; color:#5a6a7a; font-weight:700;">Request Number</div>';
            h += '<div style="font-size:18px; font-weight:700; color:#1a1a1a;">' + esc(swapNumber) + '</div>';
            h += '<div style="font-size:12px; padding-top:3px;"><a href="' + swapPortalUrl + '" style="color:#AF272F; font-weight:700; text-decoration:none;">Review in CredX &rarr;</a></div>';
            h += '</td>';
            h += '<td align="right" valign="middle" style="padding:12px 16px;">' + swapActionPill + swapTypePill + '</td>';
            h += '</tr></tbody></table>';

            h += sec('Reallocation Summary', 28);
            h += '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0"><tbody><tr>';
            h += '<td width="33%" valign="top" style="padding-right:6px;"><div style="' + TILE + '"><div style="' + TILE_K + '">Donor Site (&minus;)</div><div style="font-size:16px; font-family:monospace; font-weight:700; color:#E23D28; padding-top:4px;">' + esc(donorCode || '&mdash;') + '</div></div></td>';
            h += '<td width="34%" valign="top" style="padding:0 3px;"><div style="' + TILE + '"><div style="' + TILE_K + '">Donee Site (+)</div><div style="font-size:16px; font-family:monospace; font-weight:700; color:#1e8449; padding-top:4px;">' + esc(doneeCode || '&mdash;') + '</div></div></td>';
            h += '<td width="33%" valign="top" style="padding-left:6px;"><div style="background-color:#fffcf0; border:1px solid #F3D54E; border-radius:6px; padding:12px 14px;"><div style="' + TILE_K + '">Transfer Amount</div><div style="font-size:17px; font-weight:700; padding-top:3px;">' + rupee(swapAmount) + '</div></div></td>';
            h += '</tr></tbody></table>';

            h += sec('Site Limit Comparison');
            var STH = 'padding:9px 12px; background-color:#eef1f5; color:#2b3440; font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.5px; text-align:left; border-bottom:1px solid #dde3ea;';
            var STD = 'padding:10px 12px; font-size:13px; color:#1a1a1a; border-bottom:1px solid #eef1f5; vertical-align:top;';

            h += '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="border:1px solid #dde3ea; border-radius:6px;">';
            h += '<thead><tr>';
            h += '<th style="' + STH + ' width:24%;">Attribute</th>';
            h += '<th style="' + STH + ' width:38%; color:#E23D28;">Donor Site (Deducting &minus;)</th>';
            h += '<th style="' + STH + ' width:38%; color:#1e8449;">Donee Site (Receiving +)</th>';
            h += '</tr></thead><tbody>';

            h += '<tr>';
            h += '<td style="' + STD + ' color:#5a6a7a;">Customer Site Code</td>';
            h += '<td style="' + STD + ' font-family:monospace; font-weight:700;">' + esc(donorCode) + '</td>';
            h += '<td style="' + STD + ' font-family:monospace; font-weight:700;">' + esc(doneeCode) + '</td>';
            h += '</tr>';

            h += '<tr>';
            h += '<td style="' + STD + ' color:#5a6a7a;">Customer Name</td>';
            h += '<td style="' + STD + ' font-weight:600;">' + esc(donorName) + '</td>';
            h += '<td style="' + STD + ' font-weight:600;">' + esc(doneeName) + '</td>';
            h += '</tr>';

            h += '<tr>';
            h += '<td style="' + STD + ' color:#5a6a7a;">Current Limit</td>';
            h += '<td style="' + STD + ' font-weight:600;">' + rupee(donorCurrentLimit) + '</td>';
            h += '<td style="' + STD + ' font-weight:600;">' + rupee(doneeCurrentLimit) + '</td>';
            h += '</tr>';

            h += '<tr>';
            h += '<td style="' + STD + ' border-bottom:none; color:#5a6a7a;">Post-Swap Limit</td>';
            h += '<td style="' + STD + ' border-bottom:none; color:#E23D28; font-weight:700;">' + rupee(donorPostLimit) + '</td>';
            h += '<td style="' + STD + ' border-bottom:none; color:#1e8449; font-weight:700;">' + rupee(doneePostLimit) + '</td>';
            h += '</tr>';

            h += '</tbody></table>';

            h += renderApprovalHistory(swapGr, swapAmount, 'Swap Amount');

            h += sec('Take Decision');
            h += '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background-color:#fafbfc; border:1px solid #e0e6ed; border-radius:6px;"><tbody><tr><td style="padding:16px 18px;">';
            h += '<div style="font-size:12px; color:#5a6a7a; margin-bottom:12px;">Approve or reject directly via email (no portal login required), or open the request in CredX:</div>';
            h += '<table role="presentation" border="0" cellspacing="0" cellpadding="0"><tbody><tr>';
            h += '<td style="padding-right:10px;">';
            h += '<a href="' + mailtoApprove + '" target="_blank" style="display:inline-block; background-color:#27ae60; color:#ffffff; text-decoration:none; font-size:12px; font-weight:700; letter-spacing:.5px; text-transform:uppercase; padding:11px 20px; border-radius:6px;">&#10004; Approve via Email</a>';
            h += '</td>';
            h += '<td style="padding-right:10px;">';
            h += '<a href="' + mailtoReject + '" target="_blank" style="display:inline-block; background-color:#E23D28; color:#ffffff; text-decoration:none; font-size:12px; font-weight:700; letter-spacing:.5px; text-transform:uppercase; padding:11px 20px; border-radius:6px;">&#10006; Reject via Email</a>';
            h += '</td>';
            h += '<td>';
            h += '<a href="' + swapPortalUrl + '" target="_blank" style="display:inline-block; background-color:#1a1a1a; border-bottom:3px solid #F3D54E; color:#ffffff; text-decoration:none; font-size:12px; font-weight:700; letter-spacing:.5px; text-transform:uppercase; padding:11px 20px; border-radius:6px;">Review in Portal</a>';
            h += '</td>';
            h += '</tr></tbody></table>';
            h += '</td></tr></tbody></table>';

            template.print(h);
            return;
        }

        // ── 6. Generic Fallback ────────────────────────────────────────────
        var genReq = current.sysapproval ? s(current.sysapproval.getDisplayValue()) : (current.document_id ? s(current.document_id.getDisplayValue()) : 'Request');
        email.setSubject('[CredX] Action Required: Pending Approval Request - ' + genReq);

        h += '<p style="margin:0 0 4px 0; font-size:14px; color:#5a6a7a;">Dear ' + esc(approverName) + ',</p>';
        h += '<h1 style="margin:10px 0 6px 0; font-size:22px; line-height:1.3; color:#1a1a1a; font-weight:700;">An approval request is awaiting your decision</h1>';
        h += '<p style="margin:0 0 20px 0; font-size:14px; color:#5a6a7a;">Please review <b style="color:#1a1a1a;">' + esc(genReq) + '</b> in CredX to approve or reject.</p>';

        h += '<table role="presentation" cellspacing="0" cellpadding="0" border="0" style="margin-top:20px;"><tbody><tr>';
        h += '<td align="center" style="background-color:#1a1a1a; border-radius:6px; border-bottom:3px solid #F3D54E;">';
        h += '<a href="' + instanceUrl + 'uclm" target="_blank" style="display:inline-block; padding:12px 28px; font-size:13px; font-weight:700; letter-spacing:.5px; text-transform:uppercase; color:#ffffff; text-decoration:none;">Open CredX Portal</a>';
        h += '</td></tr></tbody></table>';

        template.print(h);

    } catch (ex) {
        gs.error('CLM MailScript clm_nt_ask_for_approval_script error: ' + ex.message);
        template.print('<div style="font-family: Arial, sans-serif; color: #d9534f;">Error rendering approval notification.</div>');
    }
})(current, template, email, email_action, event);
